blob = (() => {
        const m = /^data:([^;,]*)(;base64)?,([\s\S]*)$/.exec(String(dataUrl));
        if (!m) throw new Error('not a data URL');
        const bin = m[2] ? atob(m[3]) : decodeURIComponent(m[3]);
        return new Blob([Uint8Array.from(bin, (c) => c.charCodeAt(0))], { type: m[1] });
      })();
